pub enum Dispatch { Emit, // fire-and-forget, no return, no error propagation Parallel, // tokio::JoinSet, collect all, fail-open (one handler error doesn't cancel others) Serial, // sequential, fail-open Bail, // sequential, fail-fast (first error aborts) Waterfall, // sequential, each handler receives previous handler's output (chained)
