A plugin is a typed factory. It declares a config type and the service it provides; the kernel calls apply once, inserts the value, and tracks the fiber for lifecycle and hot reload. The trait lives in crates/cordis/src/registry.rs; the shape below follows PipelinePlugin (crates/ares-agent/src/pipeline.rs) and the kernel's own registry tests: use std::sync::Arc; use ares_server::{Context, Plugin, Service};
use cordis::{CordisError, RegistryService}; pub struct GreetingService { prefix: String,
} impl GreetingService { pub fn greet(&self, name: &str) -> String { format!("{}{name}", self.prefix) }
} impl Service for GreetingService {} #[derive(Default, serde::Serialize, serde::Deserialize)]
pub struct GreetingConfig { pub prefix: String,
} pub struct GreetingPlugin; impl Plugin for GreetingPlugin { type Config = GreetingConfig; type Provides = GreetingService; fn apply( &self, _ctx: &Arc<Context>, config: Self::Config, ) -> Result<Arc<Self::Provides>, CordisError> { Ok(Arc::new(GreetingService { prefix: config.prefix })) }
} Register through the kernel registry and pull the service back: let ctx = Context::new_root();
let registry = RegistryService::new(); registry.register( &ctx, GreetingPlugin, GreetingConfig { prefix: "hello, ".to_string() },
)?; let greeting = ctx.get::<GreetingService>().expect("provided by apply");
assert_eq!(greeting.greet("ares"), "hello, ares"); To expose the same plugin to the entries loader, add a string-keyed factory. The closure-free function form follows the capability-crate factories in crates/ares-tools/src/plugins.rs: fn factory_greeting( ctx: &Arc<Context>, config: &serde_json::Value,
) -> Result<cordis::FiberId, cordis::CordisError> { let cfg: GreetingConfig = serde_json::from_value(config.clone()) .map_err(|e| CordisError::Configuration(e.to_string()))?; let svc = GreetingService { prefix: cfg.prefix }; tokio::task::block_in_place(|| { tokio::runtime::Handle::current().block_on(ctx.plugin(svc)) })
} // Pull the factory table from the context, then add the key
// after register_plugins(&registry).
let factories = ctx.get::<ares_server::PluginRegistry>().expect("registry");
factories.register("Greeting", std::sync::Arc::new(factory_greeting)); An entry can now name it: [[entry]]
